// sync-missing-prod-to-dev.js — copy only the data that's MISSING in Dev DB, from Production DB
// Run: node scripts/sync-missing-prod-to-dev.js
//
// Two strategies:
//  - UUID_TABLES: id (uuid) is shared between prod and dev. We fetch existing dev ids
//    and insert only the prod rows whose id isn't already in dev. Existing dev rows
//    are left untouched.
//  - FULL_RELOAD_TABLES: bigint identity PK, ids never matched between prod/dev after
//    the first sync. These were TRUNCATEd in dev beforehand, so we just reinsert
//    everything from production (id stripped, regenerated by dev).

const { createClient } = require('@supabase/supabase-js')

const PROD_URL = 'https://jtjironqszdfsflvdvld.supabase.co'
const PROD_KEY = 'sb_publishable_5poaDQcuzIBuWUw2eKuxJw_VFHT-iui'
const DEV_URL  = 'https://hmcppjhjybqmlxhdbmbh.supabase.co'
const DEV_KEY  = 'sb_publishable_f1cEeDCEH6m2NjkiJlJclQ_zle7sXnI'

const prod = createClient(PROD_URL, PROD_KEY)
const dev  = createClient(DEV_URL,  DEV_KEY)

const BATCH = 500

// uuid PK shared between prod/dev — insert only rows missing in dev, never touch existing rows
const UUID_TABLES = [
  'lotus_orders',
  'wet_market_orders',
  'production_assignments',
  'withdrawal_requests',
  'makro_orders',
  'production_actual',
  'rm_allocation_snapshots', // currently empty in dev — every row is "missing"
]

// bigint identity PK — dev table was TRUNCATEd, full reload, id stripped/regenerated
const FULL_RELOAD_TABLES = [
  { name: 'mas_yield' },
  { name: 'production_plan_100' },
  { name: 'picking_unit_master' },
  { name: 'mas_raw_basket' },
]

async function fetchAllIds(client, name) {
  const ids = new Set()
  let from = 0
  for (;;) {
    const { data, error } = await client.from(name).select('id').range(from, from + BATCH - 1)
    if (error) throw new Error(`fetch ids error: ${error.message}`)
    if (data.length === 0) break
    for (const row of data) ids.add(row.id)
    if (data.length < BATCH) break
    from += BATCH
  }
  return ids
}

async function fetchAllRows(client, name, count) {
  const rows = []
  for (let from = 0; from < count; from += BATCH) {
    const { data, error } = await client.from(name).select('*').range(from, from + BATCH - 1)
    if (error) throw new Error(`read error at ${from}: ${error.message}`)
    rows.push(...data)
    process.stdout.write(`\r  ${name}: read ${rows.length}/${count}   `)
  }
  return rows
}

async function insertBatches(client, name, rows) {
  for (let i = 0; i < rows.length; i += BATCH) {
    const batch = rows.slice(i, i + BATCH)
    const { error } = await client.from(name).insert(batch)
    if (error) throw new Error(`insert error at ${i}: ${error.message}`)
    process.stdout.write(`\r  ${name}: inserted ${Math.min(i + BATCH, rows.length)}/${rows.length}   `)
  }
}

async function syncMissingUuidTable(name) {
  const { count, error: cErr } = await prod.from(name).select('*', { count: 'exact', head: true })
  if (cErr) throw new Error(`count error: ${cErr.message}`)
  if (count === 0) {
    process.stdout.write(`  ${name}: 0 rows in production — skipped\n`)
    return
  }

  const devIds = await fetchAllIds(dev, name)
  const prodRows = await fetchAllRows(prod, name, count)
  const missing = prodRows.filter((r) => !devIds.has(r.id))

  if (missing.length === 0) {
    process.stdout.write(`\r  ${name}: already in sync (0 missing)            \n`)
    return
  }

  await insertBatches(dev, name, missing)
  process.stdout.write(`\r  ${name}: done (${missing.length} missing rows inserted)            \n`)
}

async function syncFullReload(name) {
  const { count, error: cErr } = await prod.from(name).select('*', { count: 'exact', head: true })
  if (cErr) throw new Error(`count error: ${cErr.message}`)
  if (count === 0) {
    process.stdout.write(`  ${name}: 0 rows — skipped\n`)
    return
  }

  const rows = await fetchAllRows(prod, name, count)
  const toInsert = rows.map(({ id, ...rest }) => rest) // strip id, dev regenerates identity
  await insertBatches(dev, name, toInsert)
  process.stdout.write(`\r  ${name}: done (${rows.length} rows reloaded)            \n`)
}

async function main() {
  console.log('=== Sync MISSING data: Production -> Dev ===\n')
  let ok = 0, fail = 0

  for (const name of UUID_TABLES) {
    try {
      await syncMissingUuidTable(name)
      ok++
    } catch (e) {
      console.error(`\n  ERROR [${name}]: ${e.message}`)
      fail++
    }
  }

  for (const { name } of FULL_RELOAD_TABLES) {
    try {
      await syncFullReload(name)
      ok++
    } catch (e) {
      console.error(`\n  ERROR [${name}]: ${e.message}`)
      fail++
    }
  }

  console.log(`\n=== Done: ${ok} ok, ${fail} failed ===`)
}

main()
